const sections = (s: Spec) => [
  ...s.notes.map((note, i) => ({
    title: `${titles[i]}: ${s.angle}`,
    paragraphs: [
      note,
      `${note} In this ${s.angle} routine, keep the record tied to the invoice or supplier identifier, approved source location, current status, accountable owner, and next review date. A practical outsourced accounts payable desk can sort, compare, prepare, follow up, and preserve evidence; the company’s designated finance employee retains decisions about approval, accounting treatment, vendor records, and payment release.`,
    ],
  })),
  {
    title: `Route-local operating test for ${s.angle}`,
    paragraphs: [
      `On August 21, 2026, use a route-local test for ${s.angle} before handing work to the next reviewer. Begin with one ordinary invoice, one incomplete or conflicting packet, and one item that needs an employee decision. For each example, record the source location, the supplier or invoice identifier, the field being examined, the observation made, the unresolved question, the named owner, and the next review date. Then ask a second outsourced accounts payable specialist to follow the record without relying on memory or a private message. If that person cannot identify what was checked or why the item stopped, improve the note rather than marking the work complete. This test is particularly useful when work crosses time zones or shifts, because the packet must explain its own context. Keep the test focused on preparation and evidence: it may reveal a missing receipt, a coding question, an approval mismatch, or a duplicate signal, but it must not turn a support role into an approver. Compare the result with the company’s written procedure, retain the reviewer’s observation, and route policy questions to the responsible finance employee. A strong ${s.angle} record is not the one with the most confident label; it is the one that lets an authorized person make a timely, explainable decision while preserving the original source and the reason for every stop.`,
    ],
  },
];
